 -- 3. 테이블 생성

CREATE TABLE  smartform.MSF_REQUEST (
         REQUEST_KEY    NUMERIC(20)    NOT NULL
        , CRET_IP    VARCHAR(20)
        , CRET_DT    TIMESTAMP
        , CRET_ID    VARCHAR(50)
        , AMD_IP    VARCHAR(20)
        , AMD_DT    TIMESTAMP
        , AMD_ID    VARCHAR(50)
        , MANAGER_CD    VARCHAR(20)    NOT NULL
        , MANAGER_NM    VARCHAR(100)
        , AGENT_CD    VARCHAR(20)    NOT NULL
        , AGENT_NM    VARCHAR(100)
        , SHOP_CD    VARCHAR(20)
        , SHOP_NM    VARCHAR(100)
        , REAL_SHOP_NM    VARCHAR(100)
        , CPNT_ID    VARCHAR(20)
        , CPNT_NM    VARCHAR(100)
        , CNTPNT_SHOP_CD    VARCHAR(20)
        , CNTPNT_SHOP_NM    VARCHAR(100)
        , REQ_BUY_TYPE_CD    VARCHAR(10)    NOT NULL
        , OPEN_TYPE_CD    VARCHAR(10)
        , SERVICE_TYPE_CD    VARCHAR(10)    NOT NULL
        , OPER_TYPE_CD    VARCHAR(10)    NOT NULL
        , CSTMR_TYPE_CD    VARCHAR(10)    NOT NULL
        , IDENTITY_CERT_TYPE_CD    VARCHAR(2)    NOT NULL
        , KNOTE_IDENTITY_SCAN_CSTMR_NM    VARCHAR(60)
        , KNOTE_IDENTITY_ESS_NO    VARCHAR(13)
        , KNOTE_IDENTITY_TYPE_CD    VARCHAR(2)
        , KNOTE_IDENTITY_SCAN_DT    TIMESTAMP
        , KNOTE_SCAN_ID    VARCHAR(500)
        , FATH_TRG_YN    CHAR(1)    DEFAULT 'N'     NOT NULL
        , FATH_TRG_IDENTITY_CERT_TYPE_CD    VARCHAR(2)
        , FATH_TRANSAC_ID    VARCHAR(30)
        , FATH_CMPLT_NTFY_DATE    VARCHAR(14)
        , FATH_TEL_NO    VARCHAR(11)
        , FATH_MOBILE_FN_NO    VARCHAR(3)
        , FATH_MOBILE_MN_NO    VARCHAR(4)
        , FATH_MOBILE_RN_NO    VARCHAR(4)
        , AUTH_INFO    VARCHAR(255)
        , IDENTITY_TYPE_CD    VARCHAR(2)
        , IDENTITY_ISSU_DATE    VARCHAR(8)
        , IDENTITY_ISSU_REGION    VARCHAR(100)
        , SELF_ISSU_NO    VARCHAR(250)
        , DRIVE_LICNS_NO    VARCHAR(250)
        , OPEN_NO    VARCHAR(11)
        , CONTRACT_NUM    VARCHAR(10)
        , PROD_TYPE_CD    VARCHAR(2)
        , PROD_ID    VARCHAR(20)
        , PROD_NM    VARCHAR(100)
        , REQ_PHONE_SN    VARCHAR(50)
        , REQ_MODEL_NM    VARCHAR(50)
        , SNTY_CAPAC_CD    VARCHAR(3)
        , SNTY_COLOR_CD    VARCHAR(3)
        , REQ_MODEL_COLOR    VARCHAR(100)
        , SHOP_USM_ID    VARCHAR(20)
        , USIM_KINDS_CD    VARCHAR(8)
        , REQ_USIM_SN    VARCHAR(50)
        , REQ_USIM_NM    VARCHAR(30)
        , EID    VARCHAR(32)
        , IMEI1    VARCHAR(19)
        , IMEI2    VARCHAR(19)
        , ESIM_PHONE_ID    VARCHAR(20)
        , UPLOAD_PHONE_SRL_NO    NUMERIC(22)
        , REQ_WANT_FN_NO    VARCHAR(4)
        , REQ_WANT_MN_NO    VARCHAR(4)
        , REQ_WANT_RN_NO    VARCHAR(4)
        , INSR_CD    VARCHAR(2)
        , INSR_PROD_CD    VARCHAR(10)
        , CLAUSE_INSURANCE_YN    CHAR(1)    DEFAULT 'N'     NOT NULL
        , CLAUSE_INSR_PROD_YN    CHAR(1)    DEFAULT 'N'     NOT NULL
        , INSR_AUTH_INFO    VARCHAR(255)
        , PRNTS_CONTRACT_NUM    VARCHAR(10)
        , PRNTS_MOBILE_NO    VARCHAR(11)
        , JEHU_PARTNER_TYPE_CD    VARCHAR(30)
        , JEHU_PROD_TYPE_CD    VARCHAR(30)
        , REQ_ADDITION_LIST_NM    VARCHAR(3000)
        , REQ_ADDITION_PRICE    NUMERIC(10)
        , PHONE_PAYMENT_YN    CHAR(1)    DEFAULT 'N'     NOT NULL
        , ON_OFF_TYPE_CD    CHAR(1)    NOT NULL
        , SO_CD    CHAR(1)
        , OPEN_REQ_DT    TIMESTAMP
        , REQ_IN_DAY    TIMESTAMP
        , CLAUSE_PRI_COLLECT_YN    CHAR(1)    DEFAULT 'N'     NOT NULL
        , CLAUSE_PRI_OFFER_YN    CHAR(1)    DEFAULT 'N'     NOT NULL
        , CLAUSE_ESS_COLLECT_YN    CHAR(1)    DEFAULT 'N'     NOT NULL
        , CLAUSE_PRI_TRUST_YN    CHAR(1)    DEFAULT 'N'     NOT NULL
        , CLAUSE_PRI_AD_YN    CHAR(1)    DEFAULT 'N'     NOT NULL
        , CLAUSE_CONFIDENCE_YN    CHAR(1)    DEFAULT 'N'     NOT NULL
        , CLAUSE_FATH_YN    CHAR(1)    DEFAULT 'N'     NOT NULL
        , NW_BLCK_AGRM_YN    CHAR(1)    DEFAULT 'N'     NOT NULL
        , APP_BLCK_AGRM_YN    CHAR(1)    DEFAULT 'N'     NOT NULL
        , BLCK_APP_DIV_CD    VARCHAR(10)
        , SO_TRNS_AGRM_YN    CHAR(1)    DEFAULT 'N'     NOT NULL
        , CLAUSE_JEHU_YN    CHAR(1)    DEFAULT 'N'     NOT NULL
        , CLAUSE_RENTAL_MODEL_CP_YN    CHAR(1)    DEFAULT 'N'     NOT NULL
        , CLAUSE_RENTAL_MODEL_CP_PR_YN    CHAR(1)    DEFAULT 'N'     NOT NULL
        , CLAUSE_RENTAL_SERVICE_YN    CHAR(1)    DEFAULT 'N'     NOT NULL
        , CLAUSE_MPPS35_YN    CHAR(1)    DEFAULT 'N'     NOT NULL
        , CLAUSE_FINANCE_YN    CHAR(1)    DEFAULT 'N'     NOT NULL
        , CLAUSE_5G_COVERAGE_YN    CHAR(1)    DEFAULT 'N'     NOT NULL
        , PERSONAL_INFO_COLLECT_AGREE_YN    CHAR(1)    DEFAULT 'N'     NOT NULL
        , OTHERS_TRNS_AGREE_YN    CHAR(1)    DEFAULT 'N'     NOT NULL
        , CLAUSE_SENSI_COLLECT_YN    CHAR(1)    DEFAULT 'N'     NOT NULL
        , CLAUSE_SENSI_OFFER_YN    CHAR(1)    DEFAULT 'N'     NOT NULL
        , CLAUSE_PARTNER_OFFER_YN    CHAR(1)    DEFAULT 'N'     NOT NULL
        , OTHERS_TRNS_KT_AGREE_YN    CHAR(1)    DEFAULT 'N'     NOT NULL
        , OTHERS_AD_RECEIVE_AGREE_YN    CHAR(1)    DEFAULT 'N'     NOT NULL
        , KT_COUNSEL_AGREE_YN    CHAR(1)    DEFAULT 'N'     NOT NULL
        , COMBINE_SOLO_TYPE_YN    CHAR(1)    DEFAULT 'N'     NOT NULL
        , COMBINE_SOLO_YN    CHAR(1)    DEFAULT 'N'     NOT NULL
        , ETC_SPECIAL_SBST    VARCHAR(200)
        , MEMO    VARCHAR(6000)
        , REC_YN    CHAR(1)    DEFAULT 'N'     NOT NULL
        , RES_CD    VARCHAR(10)
        , RES_MSG    VARCHAR(100)
        , RES_NO    VARCHAR(20)
        , PROC_DT    TIMESTAMP
        , PROC_CD    VARCHAR(2)
        , PRO_STTUS_CD    VARCHAR(10)    NOT NULL
        , SBSC_PRO_CD    VARCHAR(10)    NOT NULL
        , SCAN_ID    VARCHAR(32)
        , APP_FORM_YN    CHAR(1)    DEFAULT 'N'     NOT NULL
        , APP_FORM_XML_YN    CHAR(1)    DEFAULT 'N'     NOT NULL
        , FILE_NM    VARCHAR(300)
        , FILE_MASK_NM    VARCHAR(300)
        , FAX_YN    CHAR(1)    DEFAULT 'N'     NOT NULL
        , FAX_NO    VARCHAR(20)
